'use strict';
// Findings are calculated from the shipped snapshot, independent of country filters.
const seasonalEvidence = countries.filter(d => seasonStats(d)).map(d => ({d, s:seasonStats(d)})).sort((a,b)=>b.s.top2-a.s.top2);
const receiptsEvidence = countries.filter(d=>num(d.travel_receipts_usd_million)!==null).sort((a,b)=>Number(b.travel_receipts_usd_million)-Number(a.travel_receipts_usd_million));
const canadaEvidence = byName('Canada');
document.getElementById('evidence').innerHTML = `
<div class="panel-head"><div><p class="eyebrow">FINDINGS ACROSS THE DATASET</p><h2>What matters for tourism planning</h2><p class="sub">These findings describe the full snapshot, independently of the country controls above.</p></div></div>
<div class="country-grid">
<article class="card"><h3>Demand is concentrated differently</h3><p>In 2024, the two busiest months accounted for ${seasonalEvidence.map(({d,s})=>`${fmt(s.top2)}% of accommodation nights in ${esc(d.country)}`).join(', ')}. Only these three countries have verified monthly data here.</p>${source(seasonalEvidence[0].d.seasonality_source_url,'Monthly nights · Eurostat ↗')}</article>
<article class="card"><h3>Spending totals show scale</h3><p>${esc(receiptsEvidence[0].country)} recorded ${money(receiptsEvidence[0].travel_receipts_usd_million)} in 2024 travel receipts, the highest among ${receiptsEvidence.length} countries with verified data. Receipts exclude international passenger transport and are not profit or spending per visitor.</p>${source(receiptsEvidence[0].travel_receipts_source_url,'2024 receipts · OECD ↗')}</article>
<article class="card"><h3>Local impact evidence is thin</h3><p>Only ${available('resident_growth_support_pct')} of 16 countries has a verified national resident survey in this release. In Canada, ${canadaEvidence.resident_growth_support_pct}% supported continued tourism promotion in 2024. This does not establish support in any specific community.</p>${source(canadaEvidence.resident_survey_source_url,'2024 resident survey · Destination Canada ↗')}</article>
</div>
<section class="panel section-gap"><h2>Practical recommendations</h2><p class="sub">Planning proposals inferred from the evidence, not proven outcomes or forecasts.</p>
<div class="recommendations">
<article><span class="tag">01 · Test a seasonal campaign</span><h3>Pilot promotion outside Croatia’s July–August peak</h3><p><strong>Evidence:</strong> ${fmt(seasonStats(byName('Croatia')).top2)}% of 2024 accommodation nights occurred in the two peak months, compared with ${fmt(seasonStats(byName('Germany')).top2)}% in Germany. ${source(byName('Croatia').seasonality_source_url,'Source ↗')}</p><p><strong>Action:</strong> Test a small May or October campaign with participating attractions and accommodation providers, after checking opening dates, transport and local capacity.</p><p><strong>Measure success:</strong> Compare non-peak guest nights and local service demand with the same months before the pilot. Check for displacement from other months; a national pattern alone cannot prove the campaign caused a change.</p></article>
<article><span class="tag">02 · Make community evidence a requirement</span><h3>Review local resident evidence before scaling promotion</h3><p><strong>Evidence:</strong> ${16-available('resident_growth_support_pct')} countries lack a verified resident survey in this dataset. Canada’s ${canadaEvidence.resident_growth_support_pct}% national support figure cannot be transferred to other places. ${source(canadaEvidence.resident_survey_source_url,'Survey source ↗')}</p><p><strong>Action:</strong> Ask destination partners for published, anonymized aggregate resident feedback and monthly crowding or transport indicators. Document geographic coverage and survey methods before expanding a campaign.</p><p><strong>Measure success:</strong> Track aggregate support and service-pressure measures over time using consistent definitions. This website does not solicit individual responses or personal information.</p></article>
</div></section>`;
